EchoServiceAsyncWaiter::EchoServiceAsyncWaiter(
    EchoService* proxy) : proxy_(proxy) {}

EchoServiceAsyncWaiter::~EchoServiceAsyncWaiter() = default;

void EchoServiceAsyncWaiter::EchoString(
    const std::string& input, std::string* out_echoed_input) {
  base::RunLoop loop;
  proxy_->EchoString(std::move(input),
      base::BindOnce(
          [](base::RunLoop* loop,
             std::string* out_echoed_input
,
             const std::string& echoed_input) {*out_echoed_input = std::move(echoed_input);
            loop->Quit();
          },
          &loop,
          out_echoed_input));
  loop.Run();
}

std::string EchoServiceAsyncWaiter::EchoString(
    const std::string& input) {
  std::string async_wait_result;
  EchoString(std::move(input),&async_wait_result);
  return async_wait_result;
}






